
#define _GNU_SOURCE
#include <dlfcn.h>
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <stdarg.h>

#define DLSYM(sym, prefix) 	\
    if (strcmp(symbol, #sym) == 0) { \
        extern void* prefix##sym; \
		dbg_print("(epiphany dlsym) found symbol %s with handle=%p, address=%p\n", symbol, handle, &prefix##sym); \
        return &prefix##sym; \
    }

static char* dbg;
static char dbg_initualilised = 0;

static void dbg_initilialise(){
	dbg = getenv("DL_DEBUG");
	dbg_initualilised = 1;
}
static void dbg_print(const char *s, ...)
{
	if (dbg_initualilised==0){
		dbg_initilialise();
	}

    if (dbg != NULL)
    {
        va_list args;
        va_start(args, s);
        vfprintf(stderr, s, args);
    }
}

extern void *stub_dlopen(const char *, int);
extern void *stub_dlsym(void *__restrict, const char *__restrict);
extern int stub_dladdr(const void *handle, Dl_info *info);

const char* main_program_handle = "main_program";

const char* lib_libEGL_so_1_libEGL_so = "lib_libEGL_so_1_libEGL_so";
const char* lib_libGLESv2_so_2 = "lib_libGLESv2_so_2";
const char* libwebkitgtkinjectedbundle_so = "libwebkitgtkinjectedbundle_so";
const char* libgiognutls_so = "libgiognutls_so";

void* dlopen(const char *path, int mode) {
	if (path == NULL) { return &main_program_handle; }
	if (strcmp( path, "libEGL.so.1" ) == 0) { dbg_print("(epiphany dlopen) found library libEGL.so.1 (handle=%p)\n", &lib_libEGL_so_1_libEGL_so); return &lib_libEGL_so_1_libEGL_so; }
	if (strcmp( path, "libEGL.so" ) == 0) { dbg_print("(epiphany dlopen) found library libEGL.so (handle=%p)\n", &lib_libEGL_so_1_libEGL_so); return &lib_libEGL_so_1_libEGL_so; }
	if (strcmp( path, "libGLESv2.so.2" ) == 0) { dbg_print("(epiphany dlopen) found library libGLESv2.so.2 (handle=%p)\n", &lib_libGLESv2_so_2); return &lib_libGLESv2_so_2; }
	if (strcmp( path, "/usr/lib/webkitgtk-6.0/injected-bundle/libwebkitgtkinjectedbundle.so" ) == 0) { dbg_print("(epiphany dlopen) found library /usr/lib/webkitgtk-6.0/injected-bundle/libwebkitgtkinjectedbundle.so (handle=%p)\n", &libwebkitgtkinjectedbundle_so); return &libwebkitgtkinjectedbundle_so; }
	if (strcmp( path, "/usr/lib/gio/modules/libgiognutls.so" ) == 0) { dbg_print("(epiphany dlopen) found library /usr/lib/gio/modules/libgiognutls.so (handle=%p)\n", &libgiognutls_so); return &libgiognutls_so; }

	fprintf(stderr, "(epiphany dlopen) WARNING: failed for path %s\n", path);	return stub_dlopen(path, mode);
}

